export default function collectHiringStories({
  body,
  statusCode,
  bodyEncoding,
  previousState,
  story,
}) {
  let state;
  if (previousState === null) {
    if (
      statusCode < 200 ||
      statusCode >= 300 ||
      bodyEncoding !== null ||
      !body ||
      typeof body !== "object" ||
      !Array.isArray(body.hits)
    )
      throw new Error("Hacker News search did not return a successful JSON hit list.");
    const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;
    for (const hit of body.hits)
      if (
        !hit ||
        typeof hit.created_at !== "string" ||
        !Number.isFinite(Date.parse(hit.created_at))
      )
        throw new Error("Search story has an invalid creation timestamp.");
    const ids = body.hits
      .filter((hit) => Date.parse(hit.created_at) > cutoff)
      .map((hit) => {
        const id = Number(hit.objectID);
        if (!Number.isSafeInteger(id) || id <= 0)
          throw new Error("Search story has an invalid objectID.");
        return id;
      });
    state = { index: 0, ids, commentIds: [] };
  } else {
    const { index, ids, commentIds } = previousState;
    if (
      !Number.isSafeInteger(index) ||
      index < 0 ||
      index >= ids.length ||
      story?.id !== ids[index] ||
      story.type !== "story" ||
      (story.kids !== undefined && !Array.isArray(story.kids))
    )
      throw new Error("Hiring story does not match this read frame.");
    const kids = story.kids ?? [];
    if (kids.some((id) => !Number.isSafeInteger(id) || id <= 0))
      throw new Error("Invalid hiring comment ID.");
    state = { index: index + 1, ids, commentIds: [...commentIds, ...kids] };
  }
  return { state, itemId: state.ids[state.index] ?? 1, more: state.index < state.ids.length };
}

