export function cleanHiringText(text) {
  if (typeof text !== "string" || !text.trim()) throw new Error("Hiring comment has no text.");
  return text
    .replace(/&#x2F;/g, "/")
    .replace(/&#x27;/g, "'")
    .replace(/&\w+;/g, " ")
    .replace(/<[^>]*>/g, "")
    .replace(/\|\s*/g, "| ")
    .replace(/\s+/g, " ")
    .replace(/\s*(https?:\/\/[^\s]+)\s*/g, "\n$1\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}
export default function collectHiringComments({ commentIds, previousState, comment }) {
  let state;
  if (previousState === null) state = { index: 0, selected: [] };
  else {
    const { index, selected } = previousState;
    if (
      !Number.isSafeInteger(index) ||
      index < 0 ||
      index >= commentIds.length ||
      comment?.id !== commentIds[index] ||
      comment.type !== "comment" ||
      comment.deleted ||
      comment.dead
    )
      throw new Error("Hiring comment is missing, deleted or does not match this read frame.");
    const text = cleanHiringText(comment.text);
    state = {
      index: index + 1,
      selected: selected.length < 5 ? [...selected, { id: comment.id, text }] : selected,
    };
  }
  return { state, itemId: commentIds[state.index] ?? 1, more: state.index < commentIds.length };
}

