export const hiringFields = [
  "company",
  "title",
  "location",
  "type",
  "work_location",
  "salary",
  "description",
  "apply_url",
  "company_url",
];
export function validateHiringResult(result) {
  if (!result || typeof result !== "object" || Array.isArray(result))
    throw new Error("Expected a hiring record object.");
  for (const key of Object.keys(result))
    if (!hiringFields.includes(key)) throw new Error("Unexpected hiring field.");
  for (const key of hiringFields)
    if (result[key] !== undefined && result[key] !== null && typeof result[key] !== "string")
      throw new Error("Invalid hiring field " + key);
  if (
    result.type !== undefined &&
    result.type !== null &&
    !["FULL_TIME", "PART_TIME", "CONTRACT", "INTERNSHIP", "FREELANCE"].includes(result.type)
  )
    throw new Error("Invalid employment type.");
  if (
    result.work_location !== undefined &&
    result.work_location !== null &&
    !["REMOTE", "HYBRID", "ON_SITE"].includes(result.work_location)
  )
    throw new Error("Invalid work arrangement.");
  return Object.fromEntries(
    hiringFields.filter((key) => Object.hasOwn(result, key)).map((key) => [key, result[key]]),
  );
}
export default function collectHiringResults({ selected, previousState, completion }) {
  let state;
  if (previousState === null) state = { index: 0, plans: [] };
  else {
    const { index, plans } = previousState;
    if (
      !Number.isSafeInteger(index) ||
      index < 0 ||
      index >= selected.length ||
      plans.length !== index
    )
      throw new Error("Invalid hiring model frame.");
    state = {
      index: index + 1,
      plans: [
        ...plans,
        { commentId: selected[index].id, result: validateHiringResult(completion) },
      ],
    };
  }
  return {
    state,
    text: selected[state.index]?.text ?? "unused-completed-frame",
    more: state.index < selected.length,
  };
}

