export default function collectHiringReceipts({ plans, previousState, records }) {
  let state;
  if (previousState === null) state = { index: 0, receipts: [] };
  else {
    const { index, receipts } = previousState;
    if (
      !Number.isSafeInteger(index) ||
      index < 0 ||
      index >= plans.length ||
      receipts.length !== index ||
      !Array.isArray(records) ||
      records.length !== 1 ||
      typeof records[0]?.id !== "string" ||
      !records[0].id
    )
      throw new Error("Airtable did not confirm exactly one hiring record.");
    state = {
      index: index + 1,
      receipts: [...receipts, { commentId: plans[index].commentId, recordId: records[0].id }],
    };
  }
  const result = plans[state.index]?.result ?? {};
  const fields = Object.fromEntries(
    Object.entries(result).filter(([key]) => key !== "work_location"),
  );
  return {
    state,
    records: [{ fields }],
    more: state.index < plans.length,
    count: state.receipts.length,
  };
}
